import { ApiError } from "@/lib/api-error";
import { resolveCost } from "@/lib/chat/service";
import { prisma } from "@/lib/db";
import { streamChatCompletion, type UsageInfo } from "@/lib/openrouter/client";
import { requireApiKey } from "@/lib/settings";
import { assertWithinBudget } from "@/lib/usage";

const VISION_TIMEOUT_MS = 90_000;

/**
 * Asks the default model to transcribe and describe an image. Uses the same key, budget check, and usage records as
 * every other AI call. The reply is generated by a model, so it can contain mistakes.
 */
export async function describeImage(params: { bytes: Uint8Array; mimeType: string; signal?: AbortSignal }): Promise<string> {
  const { key } = await requireApiKey();
  const settings = await prisma.appSettings.findUnique({ where: { id: 1 }, select: { defaultModelId: true } });
  const modelId = settings?.defaultModelId;
  if (!modelId) throw new ApiError(400, "model_required", "Choose a default model (one that can read images) before adding images.");
  await assertWithinBudget();

  const timeout = AbortSignal.timeout(VISION_TIMEOUT_MS);
  const signal = params.signal ? AbortSignal.any([params.signal, timeout]) : timeout;
  const dataUrl = `data:${params.mimeType};base64,${Buffer.from(params.bytes).toString("base64")}`;

  let text = "";
  let usage: UsageInfo | null = null;
  try {
    for await (const event of streamChatCompletion({
      apiKey: key,
      body: {
        model: modelId,
        temperature: 0.1,
        messages: [
          {
            role: "user",
            content: [
              {
                type: "text",
                text: "Transcribe all text visible in this image exactly as written, then describe what the image shows in a few sentences. Use plain text. If the image has no text, say so.",
              },
              { type: "image_url", image_url: { url: dataUrl } },
            ],
          },
        ],
      },
      signal,
    })) {
      if (event.type === "delta") text += event.text;
      else if (event.type === "usage") usage = event.usage;
    }
  } catch (error) {
    await prisma.usageRecord.create({ data: { modelId, status: "error" } }).catch(() => undefined);
    throw error;
  }

  const cost = await resolveCost(modelId, key, usage);
  await prisma.usageRecord.create({
    data: {
      modelId,
      promptTokens: usage?.promptTokens ?? null,
      completionTokens: usage?.completionTokens ?? null,
      totalTokens: usage?.totalTokens ?? null,
      costUsd: cost.costUsd,
      costSource: cost.source,
      status: "complete",
    },
  });
  const result = text.trim();
  if (!result) throw new ApiError(502, "empty_reply", "The model returned nothing for that image. Try a model that supports image input.");
  return result;
}
